WITH gated AS (SELECT model FROM llm_gateway.usage_log WHERE {{ time_filter('timestamp') }} AND model != '' GROUP BY model HAVING count() >= 100) SELECT toStartOfHour(timestamp) AS time, 'guard blocks' AS label, round(100 * sum(guard_blocks) / count(), 3) AS value FROM llm_gateway.request_signals WHERE {{ time_filter('timestamp') }} AND model IN ({{ gf_str_multi('model') }}) AND model IN (SELECT model FROM gated) GROUP BY time HAVING count() >= 5 ORDER BY time